#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;
    while (t--) {
        int n;
        cin >> n;
        vector<int> a(n);
        int even = 0, odd = 0;
        for (auto& x : a) {
            if (x % 2 == 0) even++;
            else odd++;
        }

        if (even == 0 || odd == 0) {
            cout << 0 << '\n';
        } else {
            int steps_even = odd;
            int steps_odd = even;
            cout << min(steps_even, steps_odd) << '\n';
        }
    }

    return 0;
}
